/**
 * [INPUT]: depends on node:fs/promises, node:path, node:url; depends on ALL_ROUTES and getSiteUrl from ../src/seo/routes.ts; depends on getRouteRelativeHtmlPath, renderRouteHtml, generateSitemapXml, and generateRobotsTxt from ../src/seo/ssg.ts
 * [OUTPUT]: exports getRouteOutputPath and prerenderSeoDist; runs as post-build CLI writing 76 static localized index.html pages, sitemap.xml, and robots.txt into dist/
 * [POS]: thin Node ESM filesystem runner in scripts/, invoked after `vite build` to materialize build-time SSG artifacts generated by src/seo/ssg.ts
 * [PROTOCOL]: Update this header on change, then check GEMINI.md
 */

import { mkdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { pathToFileURL } from 'node:url'
import { ALL_ROUTES, getSiteUrl } from '../src/seo/routes.ts'
import {
  generateRobotsTxt,
  generateSitemapXml,
  getRouteRelativeHtmlPath,
  renderRouteHtml,
} from '../src/seo/ssg.ts'

export function getRouteOutputPath(distDir, route) {
  return path.join(distDir, ...getRouteRelativeHtmlPath(route))
}

export async function prerenderSeoDist({
  distDir = path.resolve(process.argv[2] ?? 'dist'),
  siteUrl = getSiteUrl(),
  lastmod = process.env.MOKLU_SSG_LASTMOD || undefined,
} = {}) {
  const templatePath = path.join(distDir, 'index.html')
  const templateHtml = await readFile(templatePath, 'utf8')
  const normalizedBase = getSiteUrl(siteUrl)

  const writtenFiles = []
  for (const route of ALL_ROUTES) {
    const html = renderRouteHtml(templateHtml, route, normalizedBase)
    const outputPath = getRouteOutputPath(distDir, route)
    await mkdir(path.dirname(outputPath), { recursive: true })
    await writeFile(outputPath, html, 'utf8')
    writtenFiles.push(outputPath)
  }

  const sitemapPath = path.join(distDir, 'sitemap.xml')
  await writeFile(sitemapPath, generateSitemapXml(normalizedBase, lastmod), 'utf8')

  const robotsPath = path.join(distDir, 'robots.txt')
  await writeFile(robotsPath, generateRobotsTxt(normalizedBase), 'utf8')

  return {
    ok: true,
    siteUrl: normalizedBase,
    routesWritten: writtenFiles.length,
    sitemapUrls: ALL_ROUTES.length,
    sitemapPath,
    robotsPath,
  }
}

const isMainEntry =
  typeof process !== 'undefined' &&
  typeof process.argv?.[1] === 'string' &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href

if (isMainEntry) {
  const report = await prerenderSeoDist()
  console.log(JSON.stringify(report, null, 2))
}
